use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut transposed = Vec::new();
    for row in input.as_array() {
        let mut row_values = Vec::new();
        for col in row.as_array() {
            row_values.push(col.as_i64().unwrap());
        }
        transposed.push(row_values);
    }
    serde_json::Value::Object(transposed.into_iter().collect())
}
